//! HALL pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! Each `Pin{n}Func` enumerates the HALL functions selectable on pin `{n}` of
//! its bank; the numeric value of every variant is the 4-bit code written into
//! `PORTx.FUNC0/FUNC1`. `HALL0_INy` is input `y` of the first interface and
//! `HALL3_INy` input `y` of the second (which the driver calls
//! `HallSelect::Hall1`). Unlike the analog peripherals these codes differ per
//! pad, which is why the table is generated rather than transcribed. Code `0`
//! (generic GPIO) is omitted. Every input has several candidate pads, so routing
//! is a type-checked choice between them -- see
//! [`crate::timr::hall::Hall::new_hall0`] / [`crate::timr::hall::Hall::new_hall3`].


/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var = $val ),*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 { self as u8 }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod a {
    pad_funcs! {
        PA0 => Pin0Func { Hall0In0 = 3 },
        PA1 => Pin1Func { Hall0In1 = 3 },
        PA2 => Pin2Func { Hall0In2 = 3 },
        PA12 => Pin12Func { Hall3In0 = 2 },
        PA13 => Pin13Func { Hall3In1 = 2 },
        PA14 => Pin14Func { Hall3In2 = 1 },
        PA15 => Pin15Func { Hall3In0 = 1 },
    }
}

